using System.Diagnostics;
using System.Text.Json;
using LXMF;

namespace NomadNet.Tests;

// Generated by executing primary FileBrowser.py at f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2.
// The fixture records source SHA-256 and the disclosed headless shared-UI glyph host.
[Trait("Category", "Integration")]
public sealed class NomadNetFilePickerTests
{
    [SupportedFilesFact]
    public void ActualPrimaryListingTogglingNoticesNavigationAndCallbacksMatch()
    {
        var root = CreateDirectory();
        try
        {
            foreach (var name in new[] { "AlphaDir", "zdir", ".hidden-dir" }) Directory.CreateDirectory(Path.Combine(root, name));
            foreach (var (name, value) in new[] { ("A.txt", "1234"), ("B.txt", "B"), ("oversize.txt", "12345"),
                (".hidden", "H"), ("\ue000.txt", "P"), ("\U0001f600.txt", "E") })
                File.WriteAllText(Path.Combine(root, name), value);
            using var stream = typeof(NomadNetFilePickerTests).Assembly.GetManifestResourceStream("NomadNet.Tests.NomadNetFileBrowserVectors.json");
            Assert.NotNull(stream);
            using var fixture = JsonDocument.Parse(stream);
            Assert.Equal("f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2", fixture.RootElement.GetProperty("commit").GetString());
            var picker = new NomadNetFilePicker(root, maximumBytes: 4);
            var events = new List<(string Name, string[] Selected)>();
            picker.Changed += files => events.Add(("change", files.Select(Path.GetFileName).Select(name => name ?? "").ToArray()));
            picker.Cancelled += () => events.Add(("cancel", []));
            var rows = fixture.RootElement.GetProperty("rows").EnumerateArray().ToArray();
            Assert.Equal(rows.Length, picker.Entries.Count);
            for (var index = 0; index < rows.Length; index++)
            {
                Assert.Equal(rows[index].GetProperty("name").GetString(), picker.Entries[index].Name);
                Assert.Equal(rows[index].GetProperty("directory").GetBoolean(), picker.Entries[index].IsDirectory);
                Assert.Equal(rows[index].GetProperty("parent").GetBoolean(), picker.Entries[index].IsParent);
            }
            foreach (var step in fixture.RootElement.GetProperty("steps").EnumerateArray())
            {
                var name = step.GetProperty("name").GetString();
                picker.Open(picker.Entries.ToList().FindIndex(entry => entry.Name == name));
                Assert.Equal(step.GetProperty("selected").EnumerateArray().Select(value => value.GetString()),
                    picker.Selected.Select(Path.GetFileName));
                Assert.Equal(step.GetProperty("notice").GetBoolean(), picker.Notice is not null);
                Assert.Equal(step.GetProperty("directory").GetString() == "nomadnet-file-browser-reference" ? root : Path.Combine(root, "AlphaDir"),
                    picker.CurrentDirectory);
            }
            picker.Cancel();
            var single = new NomadNetFilePicker(root, multiple: false);
            single.Completed += files => events.Add(("single-done", files.Select(Path.GetFileName).Select(name => name ?? "").ToArray()));
            single.Open(single.Entries.ToList().FindIndex(entry => entry.Name == "A.txt"));
            var expected = fixture.RootElement.GetProperty("events").EnumerateArray().ToArray();
            Assert.Equal(expected.Length, events.Count);
            for (var index = 0; index < expected.Length; index++)
            {
                Assert.Equal(expected[index][0].GetString(), events[index].Name);
                Assert.Equal(expected[index][1].EnumerateArray().Select(value => value.GetString()), events[index].Selected);
            }
        }
        finally { Directory.Delete(root, true); }
    }

    [SupportedFilesFact]
    public async Task SelectionSnapshotsCancellationObserversAndAttachmentFieldsRemainIndependent()
    {
        var root = CreateDirectory();
        try
        {
            var first = Path.Combine(root, "one.txt");
            var second = Path.Combine(root, "two.bin");
            await File.WriteAllBytesAsync(first, [1, 2]);
            await File.WriteAllBytesAsync(second, [3, 4, 5]);
            var prior = new List<string> { first };
            var picker = new NomadNetFilePicker(root, prior);
            prior.Clear();
            var notices = new List<string>();
            picker.Log = notices.Add;
            picker.Log += _ => throw new InvalidOperationException("failing log observer");
            picker.Changed += _ => throw new InvalidOperationException("failing selection observer");
            var seen = 0;
            picker.Changed += _ => seen++;
            var snapshot = picker.Selected;
            picker.Open(picker.Entries.ToList().FindIndex(entry => entry.Name == "two.bin"));
            Assert.Equal(1, seen);
            Assert.Single(notices);
            Assert.Equal([first], snapshot);
            Assert.Throws<NotSupportedException>(() => ((IList<string>)snapshot)[0] = second);
            var completed = 0;
            picker.Completed += _ => throw new InvalidOperationException("failing completion observer");
            picker.Completed += _ => completed++;
            var committed = picker.Done();
            Assert.Equal(1, completed);
            Assert.Equal(2, notices.Count);
            Assert.Equal([first, second], committed);
            var fields = await NomadNetFilePicker.ReadAttachmentsAsync(committed);
            var files = Assert.IsType<object?[]>(fields[LxmField.FileAttachments]);
            Assert.Equal(2, files.Length);
            var data = Assert.IsType<object?[]>(files[0]);
            Assert.Equal("one.txt", data[0]);
            Assert.Equal(new byte[] { 1, 2 }, Assert.IsType<byte[]>(data[1]));
            Assert.Throws<InvalidOperationException>(picker.Refresh);
            var cancelled = new NomadNetFilePicker(root, committed);
            var cancelledCalls = 0;
            cancelled.Cancelled += () => throw new InvalidOperationException("failing cancellation observer");
            cancelled.Cancelled += () => cancelledCalls++;
            cancelled.Cancel();
            Assert.Equal(1, cancelledCalls);
            Assert.Empty(cancelled.Selected);
            Assert.Equal([first, second], committed);
            var single = new NomadNetFilePicker(root, [first], multiple: false, maximumBytes: 3);
            var order = new List<string>();
            single.Changed += _ => order.Add("change");
            single.Completed += _ => order.Add("done");
            single.Open(single.Entries.ToList().FindIndex(entry => entry.Name == "two.bin"));
            Assert.Equal([second], single.Selected);
            Assert.Equal(["change", "done"], order);
        }
        finally { Directory.Delete(root, true); }
    }

    [SupportedFilesFact]
    public async Task RegularReadsRejectOversizeCancellationMissingFilesAndDevices()
    {
        var root = CreateDirectory();
        try
        {
            var file = Path.Combine(root, "regular");
            var empty = Path.Combine(root, "empty");
            await File.WriteAllBytesAsync(file, [1, 2, 3]);
            await File.WriteAllBytesAsync(empty, []);
            Assert.True(NomadNetLocalFiles.IsRegularFile(file));
            Assert.False(NomadNetLocalFiles.IsRegularFile(root));
            Assert.False(NomadNetLocalFiles.IsRegularFile(Path.Combine(root, "missing")));
            Assert.Equal(new byte[] { 1, 2, 3 }, await NomadNetLocalFiles.ReadAsync(file, 3));
            Assert.Empty(await NomadNetLocalFiles.ReadAsync(empty, 0));
            await Assert.ThrowsAsync<InvalidDataException>(() => NomadNetLocalFiles.ReadAsync(file, 2));
            await Assert.ThrowsAnyAsync<IOException>(() => NomadNetLocalFiles.ReadAsync(Path.Combine(root, "missing")));
            using var cancellation = new CancellationTokenSource();
            cancellation.Cancel();
            await Assert.ThrowsAnyAsync<OperationCanceledException>(() => NomadNetLocalFiles.ReadAsync(file, cancellationToken: cancellation.Token));
            var device = OperatingSystem.IsWindows() ? "NUL" : "/dev/null";
            Assert.False(NomadNetLocalFiles.IsRegularFile(device));
            await Assert.ThrowsAnyAsync<IOException>(() => NomadNetLocalFiles.ReadAsync(device));
            await Assert.ThrowsAsync<InvalidOperationException>(() => NomadNetFilePicker.ReadAttachmentsAsync([]));
            using var interrupted = new CancellationTokenSource();
            IEnumerable<string> InterruptedPaths()
            {
                yield return file;
                interrupted.Cancel();
                yield return empty;
            }
            await Assert.ThrowsAnyAsync<OperationCanceledException>(() =>
                NomadNetFilePicker.ReadAttachmentsAsync(InterruptedPaths(), interrupted.Token));
        }
        finally { Directory.Delete(root, true); }
    }

    [SupportedFilesFact]
    public async Task CountDirectoryAndAggregateByteLimitsDoNotMutateTheSelection()
    {
        var root = CreateDirectory();
        try
        {
            var file = Path.Combine(root, "regular");
            await File.WriteAllBytesAsync(file, [1]);
            Assert.Throws<InvalidDataException>(() => new NomadNetFilePicker(root,
                Enumerable.Repeat(file, NomadNetAttachments.MaximumAttachments + 1)));
            var large = Path.Combine(root, "large");
            using (var stream = File.Create(large)) stream.SetLength(NomadNetAttachments.MaximumBytes);
            var picker = new NomadNetFilePicker(root, [large]);
            picker.Open(picker.Entries.ToList().FindIndex(entry => entry.Name == "regular"));
            Assert.NotNull(picker.Notice);
            Assert.Equal([large], picker.Selected);
            await Assert.ThrowsAsync<InvalidDataException>(() => NomadNetFilePicker.ReadAttachmentsAsync([large, file]));
            for (var index = 0; index < NomadNetFilePicker.MaximumDirectoryEntries; index++)
                File.WriteAllBytes(Path.Combine(root, index.ToString()), []);
            picker.Refresh();
            Assert.NotNull(picker.Notice);
            Assert.All(picker.Entries, entry => Assert.True(entry.IsParent));
            Assert.Equal([large], picker.Selected);
            picker.Cancel();
        }
        finally { Directory.Delete(root, true); }
    }

    [LinuxSpecialFilesFact]
    public async Task FifoDevicesAndSymbolicLinksAreRejectedWithoutBlockingOrReading()
    {
        var root = CreateDirectory();
        try
        {
            var target = Path.Combine(root, "target");
            await File.WriteAllBytesAsync(target, [1]);
            var link = Path.Combine(root, "link");
            File.CreateSymbolicLink(link, target);
            var fifo = Path.Combine(root, "fifo");
            await File.WriteAllTextAsync(Path.Combine(root, "unsafe\nname"), "generated");
            var info = new ProcessStartInfo("mkfifo") { UseShellExecute = false };
            info.ArgumentList.Add(fifo);
            using var process = Process.Start(info) ?? throw new IOException("Could not start mkfifo fixture setup.");
            await process.WaitForExitAsync();
            Assert.Equal(0, process.ExitCode);
            foreach (var path in new[] { link, fifo, "/dev/null" })
            {
                Assert.False(NomadNetLocalFiles.IsRegularFile(path));
                await Assert.ThrowsAnyAsync<IOException>(async () =>
                    await Task.Run(() => NomadNetLocalFiles.ReadAsync(path)).WaitAsync(TimeSpan.FromSeconds(10)));
            }
            var picker = new NomadNetFilePicker(root);
            Assert.DoesNotContain(picker.Entries, entry => entry.Name is "link" or "fifo" || entry.Name.Any(char.IsControl));
            Assert.Contains(picker.Entries, entry => entry.Name == "target");
        }
        finally { Directory.Delete(root, true); }
    }

    private static string CreateDirectory()
    {
        var root = Path.GetFullPath(Path.Combine("artifacts", "tests", "nomadnet-file-picker-" + Guid.NewGuid().ToString("N")));
        Directory.CreateDirectory(root);
        return root;
    }

    private sealed class LinuxSpecialFilesFactAttribute : FactAttribute
    {
        public LinuxSpecialFilesFactAttribute()
        {
            if (!OperatingSystem.IsLinux()) Skip = "Requires Linux FIFO/device metadata, symlinks and mkfifo fixture setup.";
        }

    }

    private sealed class SupportedFilesFactAttribute : FactAttribute
    {
        public SupportedFilesFactAttribute()
        {
            if (!OperatingSystem.IsWindows() && !OperatingSystem.IsLinux())
                Skip = "The safe regular-file adapter is implemented for Windows and Linux; other platforms are not claimed.";
        }
    }
}
